typedef unsigned char uint8;
typedef float rational_t;
typedef float vm_num_t;

class color32
{
public:
  union
  {
    struct { uint8 b,g,r,a; } c;
    unsigned int i;
  };

  color32( uint8 _r, uint8 _g, uint8 _b, uint8 _a=255 )
  {
    c.b = _b;
    c.g = _g;
    c.r = _r;
    c.a = _a;
  }
};

class beam
{
public:
  unsigned short add_color_effect(const color32& start_color, const color32& end_color, rational_t the_duration, rational_t the_delay, rational_t the_loop_delay, bool invert_loop);
};

typedef beam* vm_beam_t;

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;

  void pop(int size) { SP -= size; }
  char* get_SP() const { return SP; }
  bool push(char* data, int size);
};

void error(const char* message);

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual bool operator()(vm_stack& stack, entry_t entry);
  };
};

#define SLF_PARMS stack.pop(sizeof(parms_t)); parms_t *parms = (parms_t *)stack.get_SP()
#define SLF_RETURN if (!stack.push((char*)&result,sizeof(result))) error("script stack overflow")
#define SLF_DONE return true

class slf_beam_add_color_effect_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_beam_t me;

    vm_num_t start_r;
    vm_num_t start_g;
    vm_num_t start_b;

    vm_num_t end_r;
    vm_num_t end_g;
    vm_num_t end_b;

    vm_num_t duration;
    vm_num_t delay;
    vm_num_t loop_delay;
    vm_num_t invert;
  };

  virtual bool operator()( vm_stack& stack, entry_t entry )
  {
    SLF_PARMS;
    rational_t result = parms->me->add_color_effect(color32((uint8)parms->start_r,(uint8)parms->start_g,(uint8)parms->start_b,(uint8)0), color32((uint8)parms->end_r,(uint8)parms->end_g,(uint8)parms->end_b,(uint8)0), parms->duration, parms->delay, parms->loop_delay, (bool)parms->invert);
    SLF_RETURN;
    SLF_DONE;
  }
};
